  for p in [p for p in primary if p['condition']==c]:
   top1=next(x['official'] for x in p['top_budgets'] if x['fraction']==.01);top5=next(x['official'] for x in p['top_budgets'] if x['fraction']==.05);budget=next(x for x in p['daily_budgets'] if x['budget']==10);lines += [f'{c} ({CONDITION[c]}), {LABEL[p["model"]]}: window PR-AUC {p["PR_AUC"]:.6g} ({p["AP_over_prevalence"]:.4g} times prevalence); user ROC-AUC {p["user_ROC_official"]:.6g} for official insiders and {p["user_ROC_affected"]:.6g} for all affected accounts. The top1% contains {top1}/5 official insiders and the top5% {top5}/5. A daily budget of10 catches {budget["official_caught"]}/5 official insiders and {budget["affected_caught"]}/29 affected accounts on actual malicious endpoint days. Fold-specific frozen thresholds flag {p["official_flagged"]}/5 official insiders, {p["affected_flagged"]}/29 affected accounts and {p["normal_flagged"]}/3971 normal users.','']
