def table(rows,cols):
 def fmt(x):
  if x is None:return 'unavailable'
  if isinstance(x,float):return f'{x:.6g}'
  return str(x).replace('|','/').replace('\n',' ')
 if not rows:return '_None recorded._'
 return '| '+' | '.join(label for key,label in cols)+' |\n| '+' | '.join('---' for _ in cols)+' |\n'+'\n'.join('| '+' | '.join(fmt(row.get(key)) for key,label in cols)+' |' for row in rows)
def userrows(points,means=False):
 rows=[]
 for p in points:
  r={key:p.get(key) for key in ('key','condition','model','seed','users','official_total','affected_total','normal_total','user_ROC_official','user_ROC_affected','official_flagged','affected_flagged','normal_flagged')}
  for b in p['top_budgets']:
   percent=int(round(100*b['fraction']));r[f'official_top{percent}']=b['official'];r[f'affected_top{percent}']=b['affected']
  rows.append(r)
 if means:
  for c in ('C1','C2','C3','C4'):
   for n in (('F00',) if c=='C4' else MODELS):
    values=[x for x in rows if x['condition']==c and x['model']==n and x['seed'] in SEEDS]
    if len(values)==3:
     r=dict(key=f'{c}_{n}_mean',condition=c,model=n,seed='mean of 3')
     for key in ('users','official_total','affected_total','normal_total','user_ROC_official','user_ROC_affected','official_flagged','affected_flagged','normal_flagged','official_top1','official_top2','official_top5','affected_top1','affected_top2','affected_top5'):r[key]=float(np.mean([x[key] for x in values]))
     rows.append(r)
 return rows
